parameters.jsCode:
// 루프 안에서 모은 채점 결과를 담을 곳.
// SplitInBatches 루프가 끝나면 $('루프 안 노드').all()은 마지막 회차만 돌려주기 때문에
// 회차별 결과는 staticData에 쌓아야 한다.
const s = $getWorkflowStaticData('global');
s.evalResults = [];
s.pending = [];   // 패스1이 쌓는 답변 — 이전 실행 잔여가 섞이지 않게 비운다
s.startedAt = new Date().toISOString();

// 리포트가 실제 구성을 적도록 여기서 읽어 둔다. 하드코딩하면 구성이 바뀔 때 거짓이 된다
// (2026-09-15: Gemini 로 돌린 실행이 리포트에 'gemma3:4b' 로 적혀 나왔다).
// 답변 모델과 topK 는 이제 서브워크플로(RAG 코어) 안에 있어 여기서 못 본다 —
// 코어가 출력으로 알려주고 `답변 저장` 이 채운다. 여기서는 비워만 둔다.
s.answerModel = '?';
s.fallbackModel = '';
s.topK = '?';
try {
  s.judgeModel = String(($('Judge Model').params || {}).model || '?');
} catch (e) {
  s.judgeModel = '?';
}

return $input.all();

// 패스2 — 채점 결과를 기록한다. 채점 대상 정보는 루프 아이템에 다 들어 있다.
const s = $getWorkflowStaticData('global');
if (!Array.isArray(s.evalResults)) s.evalResults = [];
const item = $('채점 루프').first().json;

// 점수를 어느 모양으로 받든 읽는다.
//  · Judge Model 의 format=json 이 켜져 있으면 n8n 체인이 JSON 을 미리 파싱해
//    { grounding, relevance, ... } 객체를 그대로 넘긴다 ($json.text 는 없다).
//  · 꺼져 있으면 텍스트로 오고, qwen3 는 <think>…</think> 나 ```json 펜스를 붙인다.
// 2026-09-14: 앞의 경우를 안 보고 $json.text 만 읽어 27건 전부 "채점 파싱 실패" 가 났다.
// ── 채점 환산 — 모델이 '찾은 것' 을 0~5 로 바꾼다 ──────────────────────
// 2026-09-15: 채점 모델이 포화됐다. qwen3:4b 는 흠을 정확히 찾아 적어 놓고도 숫자는 5를 준다
// (표본 40건 실측: 배포본이 좋은 답 20건에 15/15, 나쁜 답 20건 중 12건에도 14점 이상).
// 그래서 `Judge` 에게는 **찾는 일만** 시키고(sameTopic·required·covered·gaveReason·negControl)
// 숫자는 여기서 코드가 만든다. 같은 표본에서 격차 3.9 → 5.75, 나쁜 답 만점 60% → 10%.
// `Judge` 가 옛 모양(grounding/relevance/completeness)을 돌려주면 이 블록은 비켜선다.
const listOf = (v) => String(v == null ? '' : v).replace(/·/g, ',').split(',')
  .map((t) => t.trim()).filter(Boolean);
// 2026-09-16: 모델이 불리언을 **문자열로** 돌려주는 때가 있다 (60건 중 4건 실측).
// `=== true` 로 비교하면 "true" 가 걸러져 맞는 답이 관련성 1점으로 깎인다
// (`카프카랑 RabbitMQ 중에 뭘 골라야 해?` 가 그렇게 오차단됐다).
const isTrue = (v) => v === true || String(v).trim().toLowerCase() === 'true';
// ── sameTopic 을 코드로 되받는다 (2026-09-18) ─────────────────────────────
// 채점기의 `sameTopic` 이 **재현되지 않는다.** ④ 2907 과 3412 에서 검색이 소수점까지
// 같은 26문항 중 13건(50%)의 점수가 달라졌고 10건은 관련성이 5↔1 로 뒤집혔다.
// 원인은 프롬프트가 요구한 정규화("무엇을/왜/… 로 시작해 20자 이내")를 모델이 안 지키는 것 —
// `asked` 가 의문사로 시작한 건 09-16 **0/60**, 09-18 **1/60** 이고 `answerTopic` 평균
// 길이는 48~51자다. 정규화 없이 질문 원문 vs 답변 첫 문장 원문을 비교하니 "닮았나" 로 퇴화한다.
//
// 그래서 **질문의 내용어가 답변에 하나라도 나오는가**(codeSameTopic)를 코드로 재고,
// 최종 판정은 `코드 OR 모델` 로 한다 — **둘 다 아니라고 할 때만** 다른 주제로 본다.
//   · 코드가 모델의 헛발을 구제한다 (N+1 질문에 n-plus-1 노트로 답했는데 false 였던 것들)
//   · 모델이 코드의 음차 맹점을 구제한다 (데드락↔교착상태, 리랭크↔리랭킹)
// 라벨 표본 40건 실측 — AUC 모델 0.921 / 코드 0.829 / **OR 0.884**,
// 좋은 답 오탐 2 / 3 / **1** (20건 중). 실제 두 실행 재현성 — 종합 변동 0.52 → **0.25**,
// 문항 변동 24/60 → **13/60**.
//
// 아래 토크나이저는 `근거 판정` 의 것을 **바이트 그대로** 옮긴 네 번째 사본이다.
// 갈라지면 어휘 기준이 게이트와 다른 말을 한다 — `bench/parity.py` 가 매번 대조한다.
const TAILS = ["이랑","에서","으로","에게","한테","부터","까지","보다","처럼","마다","대로",
  "밖에","조차","라도","이나","하고","에는","과는","와는","이란","라는","이라",
  "은지","는지","한지","인지","이야","예요","이에","해줘","해야","하는",
  "랑","와","과","은","는","이","가","을","를","의","에","도","만","로","다",
  "요","야","지","고","서","며","면","나","까","죠","네","군","데","해","라","게","걸","건"];
// 질문 골격어 — 꼬리를 뗀 뒤 정확히 일치하면 버린다.
// 주의: 이 목록이 비면 어휘 절이 거의 발동하지 않는다(= 3세대로 되돌아간다).
// 목록이 모자라서 생기는 실패는 항상 "통과시켜야 할 걸 막는" 쪽이다 — 누수로는 안 간다.
const STOP = new Set(("뭐 뭘 뭔 뭐야 뭐가 뭔지 무슨 무엇 어떻 어떻게 어떤 어디 언제 누가 얼마 얼마나 왜 " +
  "알려 알려줘 설명 설명해 정리 가르쳐 말해 얘기 이야기 " +
  "차이 다른 다르 달라 비교 각각 중에 중 골라 골라야 선택 고르 골랐 " +
  "써 쓰 쓸 쓴 쓰나 쓰면 쓰는 써야 썼어 썼 사용 적용 " +
  "필요 이유 방법 관계 정확 자꾸 헷갈 헷갈리 그냥 그리고 좀 진짜 혹시 대해 대한 관련 " +
  "에서 으로 에게 한테 부터 까지 보다 처럼 이랑 하고 " +
  "것 거 게 건 걸 수 때 때문 경우 정도 부분 내용 문제 이거 그거 저거 이런 그런 " +
  "있어 없어 되나 되는 된다 맞아 맞나 인가 일까 할까 하면 한다 이란 라면").split(/\s+/));

const RUN = /[가-힣]+|[A-Za-z0-9]+(?:[-+.][A-Za-z0-9]+)*/g;

function contentTokens(q) {
  const out = [], seen = new Set();
  const runs = String(q || "").match(RUN) || [];
  for (const run of runs) {
    let t = run, latin = /^[A-Za-z0-9]/.test(run);
    if (latin) {
      t = t.toLowerCase();
    } else {
      for (const tl of TAILS) {                       // 꼬리 1회만 제거
        if (t.length > tl.length && t.endsWith(tl)) { t = t.slice(0, -tl.length); break; }
      }
    }
    if (t.length < 2 || STOP.has(t)) continue;
    if (!seen.has(t)) { seen.add(t); out.push({ t, latin }); }
  }
  return out;
}

function esc(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); }
function hit(tok, latin, hay) {
  if (!latin) return hay.indexOf(tok) !== -1;
  // 영문/숫자는 단어 경계로 — "m2" 가 "m20" 에 걸리지 않게
  return new RegExp("(?:^|[^a-z0-9])" + esc(tok) + "(?![a-z0-9])").test(hay);
}

// 질문(재작성본이 있으면 그것)의 내용어 중 답변에 그대로 나타난 비율.
// 내용어가 하나도 없으면 판단 근거가 없다는 뜻이라 null 을 돌려주고, 호출부가 true 로 본다.
function topicCov(question, answer) {
  const toks = contentTokens(question);
  if (!toks.length) return null;
  const hay = String(answer || '').toLowerCase();
  let n = 0;
  for (const { t, latin } of toks) if (hit(t, latin, hay)) n++;
  return n / toks.length;
}


// ── 근거성도 코드로 — 컨텍스트에 없는 수치 (2026-09-18) ────────────────────
// 지금까지 `grounding` 은 이 분기에서 **상수 5** 였다. 노트 대조를 모델에 맡겼다가 뺐기
// 때문이다(좋은 답 절반에 헛경보, AUC 0.926→0.910, 건당 +16초). 그래서 지어낸 답
// (`fabricated`)을 **한 건도 못 잡았다** — 라벨 표본 40건에서 0/4.
//
// 대신 결정론적으로 잴 수 있는 것이 하나 있다: **답변이 든 수치가 컨텍스트에 있는가.**
// 지어낸 답의 전형이 "맞는 설명 뒤에 노트에 없는 수치·연혁·기본값을 덧붙이는" 것이고,
// 수치는 문자열로 정확히 대조된다 — 모델도, 임베딩도 필요 없다.
//
// 라벨 표본 40건 실측 — fabricated **0/4 → 3/4**, 나쁜 답 만점 **20% → 10%**,
// AUC **0.884 → 0.948**, 격차 4.0 → 4.6. 대가는 좋은 답 감점 1/20 → 2/20 한 건인데,
// 그 한 건도 **컨텍스트에 없는 수치 3개를 인용**한 답이라 깎이는 게 틀린 것은 아니다.
//
// 질문에 나온 수치는 센다(“k값을 왜 60으로 잡아?” 의 60). 한 자리 수는 목록 번호와
// 구분이 안 되므로 버린다.
const NUM_RE = /\d+(?:[.,]\d+)*%?/g;
function unsupportedNums(answer, ctx, question) {
  const hay = String(ctx || '') + ' ' + String(question || '');
  const out = new Set();
  const ms = String(answer || '').match(NUM_RE) || [];
  for (const raw of ms) {
    const tok = raw.replace(/[.,]+$/, '');
    if (tok.replace(/[%,.]/g, '').length < 2) continue;   // 한 자리 수·목록 번호는 뺀다
    if (hay.indexOf(tok) !== -1) continue;
    out.add(tok);
  }
  return out.size;
}

let derived = null;
if ($json && typeof $json.sameTopic !== 'undefined') {
  const a = $json;
  // 음성 대조군 규칙은 expect 에 표지가 실제로 있을 때만 연다. 표지가 없는 문항에
  // 모델이 제멋대로 '정답거절' 을 적어 만점을 준 일이 있다(실측).
  const neg = /\[음성 대조군\]/.test(item.expect || '') ? String(a.negControl || '') : '';
  if (neg.indexOf('정답거절') >= 0) {
    derived = { grounding: 5, relevance: 5, completeness: 5, comment: '음성 대조군 — 올바로 거절' };
  } else if (neg.indexOf('오답설명') >= 0) {
    derived = { grounding: 0, relevance: 0, completeness: 0, comment: '음성 대조군 — 볼트에 없는 주제를 설명했다' };
  } else {
    // 검색에 실제로 쓰인 질문을 본다 — 후속 질문은 재작성본이 앞 차례 주제어를 들고 있다
    // ("그건 왜 비싸?" → "리랭킹 왜 비싸?"). 원문으로 재면 내용어가 없어 판단이 불가능하다.
    const topicRatio = topicCov(item.searchQuestion || item.question, item.answer);
    const codeSame = topicRatio === null || topicRatio > 0;
    const same = codeSame || isTrue(a.sameTopic);   // 둘 다 아니라고 할 때만 false
    const req = listOf(a.required), cov = listOf(a.covered);
    const ratio = req.length ? cov.length / req.length : 1;
    const reason = isTrue(a.gaveReason);
    let comp;
    if (ratio >= 0.999) comp = reason ? 5 : 3;
    else if (ratio >= 0.5) comp = reason ? 4 : 3;
    else if (ratio > 0) comp = reason ? 3 : 2;
    else comp = reason ? 2 : 1;
    if (!same) comp = Math.min(comp, 2);
    const why = [], why0 = [];
    if (!same) why.push('질문과 다른 것을 답함');
    if (req.length && ratio < 0.999) {
      why.push('빠뜨림: ' + req.filter((x) => cov.indexOf(x) < 0).join(',').slice(0, 24));
    }
    if (!reason) why.push('이유 없이 결과만 나열');
    // 컨텍스트에 없는 수치가 몇 개인가 — 많을수록 지어냈을 공산이 크다.
    const nUnsup = unsupportedNums(item.answer, item.ctx, item.question);
    if (nUnsup) why0.push('컨텍스트에 없는 수치 ' + nUnsup + '개');
    derived = {
      // 근거성은 **노트 대조가 아니라 수치 대조**로 잰다. 노트 대조는 붙였다가 뺐다 —
      // 좋은 답 절반에 헛경보를 내면서 지어낸 답은 못 잡아 분리도를 되레 떨어뜨렸다
      // (AUC 0.926 → 0.910, 건당 +16초). 게이트 차단·자체 거절은 아래 코드가 그대로 0점을 준다.
      grounding: nUnsup === 0 ? 5 : nUnsup === 1 ? 4 : nUnsup === 2 ? 3 : 2,
      relevance: same ? 5 : 1,
      completeness: comp,
      comment: (why.concat(why0).join('; ') || '흠 없음').slice(0, 60),
    };
  }
}
const direct = derived || ($json && typeof $json.grounding !== 'undefined' ? $json : null);
const raw = String($json.text || '');
const cleaned = raw
  .replace(/<think>[\s\S]*?<\/think>/gi, '')
  .replace(/```(?:json)?/gi, '')
  .trim();
const m = cleaned.match(/\{[\s\S]*\}/);

let score = { grounding: null, relevance: null, completeness: null, comment: '채점 파싱 실패' };
if (direct) {
  score = { ...score, ...direct };
} else if (m) {
  try { score = { ...score, ...JSON.parse(m[0]) }; }
  catch (e) { score.comment = '채점 JSON 파싱 실패'; }
}
// 거절 문항은 채점 모델에 맡기지 않는다.
// 2026-09-14 실측: 음성 대조군 5건 중 4건이 올바로 거절했는데 0/0/0 을 받았고,
// 유일하게 5점을 받은 "쿠버네티스" 는 expect 에 "…라고 답해야 만점" 이라고 적혀 있었다.
// 즉 채점이 규칙이 아니라 expect 문구를 따라갔다. 반대로 오차단된 양성 문항("데드락")은
// 거절인데 5/5/5 를 받았다. 거절의 옳고 그름은 문항 종류로 이미 정해지는 것이라
// 모델이 판단할 일이 아니다 — 근거 판정·형식과 같은 이유로 구조로 강제한다.
const isNegative = /\[음성 대조군\]/.test(item.expect || '');
// 게이트를 통과했는데 모델이 스스로 거절한 경우.
// 2026-09-15: "CSRF랑 CORS" 에서 csrf.md 가 노트 선별에 안 들어가 컨텍스트에 CORS 만 있었다.
// 모델이 "CSRF 설명이 없어 비교할 수 없다" 고 정직하게 거절했는데 채점이 0/0/0 을 줬다.
// 같은 상황에서 정형 문구 "(노트에서 관련 내용을 찾지 못했어요)" 로 거절한 실행은 5/5/5 를 받았다.
// 채점이 거절의 '문구' 를 보고 갈린 것이다. 거절 여부는 코드로 판정한다.
const ans = String(item.answer || '');
const selfRefused = /찾지\s*못했|찾을\s*수\s*없|관련\s*내용이?\s*없|노트에\s*(?:관련|해당)[^.]*없|비교할\s*수\s*없|설명이?\s*없/.test(ans)
  && ans.length < 300;   // 길게 답하면서 한 줄 얹은 경우는 거절이 아니다

if (item.grounded === false || selfRefused) {
  const why = item.grounded === false ? '게이트 차단' : '모델이 근거 부족으로 거절';
  score = isNegative
    ? { grounding: 5, relevance: 5, completeness: 5, comment: '음성 대조군 — 올바로 거절 (' + why + ')' }
    : { grounding: 0, relevance: 0, completeness: 0, comment: '근거 도달 실패 — ' + why };
}


const clamp = (v) => (typeof v === 'number' && isFinite(v) ? Math.max(0, Math.min(5, v)) : null);

// ── 모델 없는 눈 ────────────────────────────────────────────────────────

// 2026-09-15: 채점 모델이 포화됐다. 실행 2499 에서 Judge(qwen3:4b, temp 0)가

// 50문항에 사실상 전부 5/5/5 를 줬고, 명백한 오답에도 5/5/5 였다. expect 에

// 감점 조건을 명시해 넣어도 마찬가지였다(직접 호출로 확인).

// 그래서 sources 만 읽는 결정론적 지표를 둘 단다. 점수·집계는 바꾸지 않는다.

// 2026-09-16: 음성 대조군의 expect 설명문에는 **가져오면 안 되는** 노트 이름이 들어 있다
  // ("spring-web-mvc.md 를 근거랍시고 통과시켰던 문항", "postgresql.md 는 한 줄 언급할 뿐").
  // 그걸 기대 노트로 세면 올바로 차단된 문항이 0/1 로 찍힌다. 음성 대조군은 아예 뺀다.
  const wantNotes = /\[음성 대조군\]/.test(item.expect || '')
    ? [] : ((item.expect || '').match(/[A-Za-z0-9_\-/]+\.md/g) || []);

const gotNotes = new Set(item.sources || []);

const expectHit = wantNotes.length

  ? wantNotes.filter((n) => gotNotes.has(n)).length + '/' + wantNotes.length : '';

const devInCtx = (item.sources || []).filter((s) => String(s).startsWith('dev/')).length;

s.evalResults.push({ expectHit, devInCtx,
  question: item.question,
  // 2턴 표시. 단발 문항은 prevQuestion 이 '' 라 리포트가 예전과 똑같이 나온다.
  prevQuestion: item.prevQuestion || '',
  searchQuestion: item.searchQuestion || '',
  ctxApplied: !!item.ctxApplied,
  prevGrounded: item.prevGrounded === undefined ? null : item.prevGrounded,
  answerChars: (item.answer || '').length,
  sources: item.sources,
  grounding: clamp(score.grounding),
  relevance: clamp(score.relevance),
  completeness: clamp(score.completeness),
  comment: String(score.comment || '').slice(0, 60),
  grounded: item.grounded,
  best: item.best,
  best2mean: item.best2mean,
  spread: item.spread,
  rawHead: direct || m ? '' : cleaned.slice(0, 120),
});
return [{ json: { done: s.evalResults.length, question: item.question } }];

const s = $getWorkflowStaticData('global');
const results = Array.isArray(s.evalResults) ? s.evalResults : [];
const startedAt = s.startedAt;

// 다음 실행으로 이월되지 않게 즉시 비운다.
// 주의: 이 아래로는 `s.evalResults` 가 아니라 위에서 잡아둔 `results` 를 써야 한다.
// 2026-09-16: expectHit 요약을 `s.evalResults` 로 읽어 **늘 빈 배열**이었고
// 리포트에 그 줄이 한 번도 안 나왔다.
s.evalResults = [];
s.startedAt = null;

if (results.length === 0) {
  return [{
    json: {
      content: '⚪ **RAG 답변 품질 평가** — 채점된 질문이 0개다.\nData Table `rag_golden_questions`에 enabled=true 행이 있는지 확인할 것.',
      results: [],
    },
  }];
}

// ── 값 다루기 ────────────────────────────────────────────────────────────
const num = (v) => (typeof v === 'number' && isFinite(v) ? v : null);
const fmt = (v) => (v === null ? '–' : v.toFixed(2));
const sum = (r) => (num(r.grounding) ?? 0) + (num(r.relevance) ?? 0) + (num(r.completeness) ?? 0);
const avg = (k) => {
  const xs = results.map((r) => num(r[k])).filter((v) => v !== null);
  return xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null;
};

// ── 집계 ─────────────────────────────────────────────────────────────────
const g = avg('grounding');
const rel = avg('relevance');
const c = avg('completeness');
const parts = [g, rel, c].filter((v) => v !== null);
const overall = parts.length ? parts.reduce((a, b) => a + b, 0) / parts.length : null;

const unparsed = results.filter((r) => num(r.grounding) === null).length;
const scored = results.filter((r) => num(r.grounding) !== null);
const perfect = scored.filter((r) => sum(r) === 15).length;
const mins = startedAt ? Math.round((Date.now() - new Date(startedAt).getTime()) / 60000) : null;

// ── 손볼 문항 ────────────────────────────────────────────────────────────
// 만점 문항은 여기 넣지 않는다. 넣으면 멀쩡한 답이 문제처럼 읽힌다.
const weakLine = (r) => {
  const tag = r.prevQuestion ? '[2턴] ' : '';
  const q = r.question.slice(0, 32);
  const sc = `근거 ${fmt(num(r.grounding))} / 관련 ${fmt(num(r.relevance))} / 완결 ${fmt(num(r.completeness))}`;
  return `• ${tag}${q}  →  ${sc}\n   ${r.comment}`;
};
const weak = scored
  .filter((r) => sum(r) < 15)
  .sort((a, b) => sum(a) - sum(b))
  .slice(0, 3)
  .map(weakLine)
  .join('\n');

// ── 2턴 요약 ─────────────────────────────────────────────────────────────
// 2턴이 하나도 없으면 줄 자체가 빠져 리포트가 예전과 한 글자도 다르지 않다.
const two = results.filter((r) => r.prevQuestion);
const twoApplied = two.filter((r) => r.ctxApplied).length;
const twoBlocked = two.filter((r) => r.prevGrounded === false).length;
const twoLine = two.length
  ? `2턴 ${two.length}문항 · 맥락 적용 ${twoApplied}` +
    (twoBlocked ? ` · ⚠️ 선행 턴 차단 ${twoBlocked}` : '')
  : '';

// ── expectHit 요약 — 회귀는 이 줄로 본다 ─────────────────────────────────
// 2026-09-16: 같은 골든을 두 번 돌려 보니 **선별 노트·expectHit 은 60/60 동일**한데
// 채점 점수만 47/60 만 같았다. 답변이 temp 0.4 라 60문항 중 50건의 문장이 매번 다르다.
// 즉 종합 점수는 ±0.1 노이즈가 있어 소수점 둘째 자리로 회귀를 판단하면 안 된다.
// expectHit(기대 노트 회수)·devInCtx 는 결정론적이라 검색·게이트·선별 회귀를 정확히 잡는다.
const full = (h) => {
  const p = String(h).split('/');
  return p[0] === p[1];
};
const withExpect = results.filter((r) => r.expectHit);
const fullCount = withExpect.filter((r) => full(r.expectHit)).length;
const devTotal = results.reduce((n, r) => n + (r.devInCtx || 0), 0);
const missList = withExpect
  .filter((r) => !full(r.expectHit))
  .map((r) => `${r.question.slice(0, 18)}(${r.expectHit})`)
  .slice(0, 4)
  .join(' · ');
const expectLine = !withExpect.length
  ? ''
  : `기대 노트 회수 **${fullCount}/${withExpect.length}** · dev 혼입 ${devTotal}` +
    (missList
      ? `\n   못 채운 것: ${missList}${withExpect.length - fullCount > 4 ? ' …' : ''}`
      : '');

// ── 본문 ─────────────────────────────────────────────────────────────────
// 모델명과 topK 를 손으로 적어 두면 구성이 바뀔 때 리포트가 거짓말을 한다.
// 2026-09-15: 실제로 Gemini 로 돌린 실행이 'gemma3:4b' 로, topK 16 이 '8' 로 적혀 나왔다.
const fallback = s.fallbackModel ? ` (폴백 ${s.fallbackModel})` : '';
const setupLine = `답변 ${s.answerModel || '?'}${fallback} / 채점 ${s.judgeModel || '?'} · 검색 topK ${s.topK || '?'}`;

// 2026-09-16: 근거성은 재지 않았다(거절이 아니면 상수 5). **2026-09-18 부터 다시 잰다** —
// 컨텍스트에 없는 수치의 개수로. 노트 대조가 아니라 문자열 대조라 결정론적이고 값이 공짜다.
// 라벨 표본 40건 실측: 지어낸 답 0/4 → 3/4, AUC 0.884 → 0.948.
const scoreLine = `근거성 ${fmt(g)}  ·  관련성 ${fmt(rel)}  ·  완결성 ${fmt(c)}  ·  (근거성 = 컨텍스트에 없는 수치)`;

const content = [
  `📊 **RAG 답변 품질 평가** · 질문 ${results.length}개${mins !== null ? ` · ${mins}분 소요` : ''}`,
  setupLine,
  '',
  `**종합 ${fmt(overall)} / 5**  ·  만점 ${perfect}/${scored.length}`,
  scoreLine,
  expectLine,
  twoLine,
  unparsed ? `⚠️ 채점 파싱 실패 ${unparsed}건` : '',
  '',
  weak ? '**손볼 문항**' : '',
  weak || '✅ 만점이 아닌 문항 없음',
]
  .filter(Boolean)
  .join('\n');

return [{
  json: {
    content: content.slice(0, 1900),
    overall,
    grounding: g,
    relevance: rel,
    completeness: c,
    perfect,
    total: scored.length,
    results,
  },
}];

// 패스1 — 답변만 만들어 쌓아둔다. 채점은 패스2에서 몰아서 한다.
// 문항마다 답변/채점 모델을 번갈아 부르면 27문항에 모델을 54번 재적재하게 되고,
// 실측상 채점 1회 91초 중 83초가 그 교체 비용이었다(순수 연산은 8초).
const s = $getWorkflowStaticData('global');
if (!Array.isArray(s.pending)) s.pending = [];

const q = $('Loop Over Questions').first().json;
// 2턴 문항이면 q.question 은 **후속** 질문이다(선행 질문은 prev_question 열에 있다).
// 채점 대상은 후속 턴의 답변 하나다 — 선행 턴은 맥락을 만들기 위한 준비 동작일 뿐이다.
// 단발 문항에서는 prevQ 가 '' 이고 아래 필드가 전부 중립값이라 예전 기록과 다르지 않다.
const prevQ = String(q.prev_question == null ? '' : q.prev_question).trim();
// 선행 턴의 결과는 `후속 턴 준비` 가 staticData 에 놓고 간다. 노드 참조($('후속 턴 준비'))로
// 읽으면 단발 문항 차례에 **앞 문항의 값**이 잡힌다 — 루프에서 노드 참조는 마지막 회차를
// 돌려주기 때문이다. `1차 준비` 가 회차마다 비우므로 여기 있는 값은 이번 회차 것뿐이다.
const mt = ($getWorkflowStaticData('global').mtLast) || {};
// 게이트 결과·검색 결과·모델 표기가 전부 코어의 출력 한 덩이에 들어 있다.
// (예전: $('근거 판정') 과 $('Pack Docs') 를 따로 읽었다 — 둘 다 이제 서브워크플로 안이다.)
const r = $('RAG 코어').first().json;
// 채점 근거는 **선별 전** top-16 이다. 선별이 떨어뜨린 노트까지 보고 채점해야
// "회수는 됐는데 선별이 버렸다" 를 점수로 잡을 수 있다. r.docs 가 그 top-16 이다.
const docs = (r.docs || []).map((d) => d.document || d);

// 리포트가 구성을 손으로 적지 않게 코어가 알려준 값을 여기서 받는다.
// `Start Run` 은 더 이상 답변 모델·검색 노드를 볼 수 없다(서브워크플로 안이다).
s.answerModel = r.answerModel || s.answerModel || '?';
s.fallbackModel = r.fallbackModel || s.fallbackModel || '';
s.topK = (r.topK === undefined || r.topK === null) ? (s.topK || '?') : r.topK;

s.pending.push({
  question: String(q.question || ''),
  expect: String(q.expect || ''),
  answer: String($json.text || ''),
  grounded: r.grounded,
  best: r.best,
  best2mean: r.best2mean,
  spread: r.spread,
  sources: Array.from(new Set(docs.map((x) => (x.metadata || {}).source).filter(Boolean))).slice(0, 4),
  prevQuestion: prevQ,                        // '' 이면 단발 문항
  searchQuestion: String(r.question || ''),   // 맥락 재작성이 실제로 코어에 넣은 질문
  ctxApplied: !!String(r.contextBlock || ''), // 맥락 블록이 실제로 붙었나
  prevGrounded: prevQ ? !!mt.prevGrounded : null,   // 선행 턴이 차단됐으면 후속 점수가 그 탓일 수 있다
  prevLead: prevQ ? String(mt.prevLead || '') : '',
  // 채점 프롬프트가 쓸 근거. 9000자로 자르는 건 기존 Judge 와 같은 기준이다.
  ctx: docs
    .map((x) => '[출처: ' + ((x.metadata || {}).source || '?') + ']\n' + (x.pageContent || ''))
    .join('\n---\n')
    .slice(0, 9000),
});

return [{ json: { done: s.pending.length, question: q.question } }];

// 패스1이 끝났다. 쌓아둔 답변을 아이템으로 펼쳐 채점 루프에 넘긴다.
const s = $getWorkflowStaticData('global');
const pending = Array.isArray(s.pending) ? s.pending : [];
s.evalResults = [];
if (pending.length === 0) return [{ json: { empty: true } }];
return pending.map((p) => ({ json: p }));

// ── 1차 준비 ────────────────────────────────────────────────────────────────
// 골든 행 하나를 받아 **코어에 처음 넘길** 질문을 고른다.
//   · prev_question 이 비어 있으면 = 단발 문항. 지금까지와 한 글자도 다르지 않게 question 을 넘긴다.
//   · 비어 있지 않으면 = 2턴 문항. 첫 턴은 **선행 질문**이고 행의 question 은 후속 질문이다.
//
// [단발이 안 변한다는 근거]
// 예전 `RAG 코어` 는 question/rawQuestion/contextBlock 자리에 각각
// {{$json.question}} / {{$json.question}} / {{""}} 를 넣었다. prev 가 비면 아래가 내놓는 것도
// 정확히 그 셋이다. 코어가 받는 입력이 바이트로 같으므로 검색·게이트·선별도 같다.
//
// 데이터테이블에 열을 새로 더하면 **기존 행의 값은 '' 가 아니라 null** 이다(실측).
// 그래서 null 을 먼저 '' 로 눕힌다.
// 선행 턴의 결과를 담을 자리를 **회차마다 비운다**. 안 비우면 단발 문항 차례에
// 앞 문항(2턴)의 값이 남아 `답변 저장` 이 그걸 읽는다.
$getWorkflowStaticData('global').mtLast = null;

const q = $json;
const s = (v) => String(v === null || v === undefined ? '' : v);
const prev   = s(q.prev_question).trim();
const follow = s(q.question);
const first  = prev || follow;

return [{
  json: {
    ...q,
    question: first,        // 코어가 검색에 쓸 질문
    rawQuestion: first,     // 코어가 답변 프롬프트에 쓸 질문
    contextBlock: '',       // 첫 턴에는 맥락이 없다
    mtPrev: prev,           // 2턴이면 선행 질문, 단발이면 ''
    mtFollow: follow,       // 행의 question — 2턴이면 후속 질문
    mtT0: Date.now(),       // 두 턴 사이 경과 초를 재려고. 세션 TTL 판정이 이걸 본다
  },
}];

// ── 후속 턴 준비 ────────────────────────────────────────────────────────────
// 선행 턴이 끝났다. ② 가 Postgres 세션으로 하는 일을 **② 의 노드 원문 그대로** 재생한다.
//
//   ②   RAG 코어 → 답변 정리 → 세션 기록 → (세션 저장) ⋯다음 차례⋯ (세션 로드) → 맥락 재작성
//   ④   RAG 코어(선행) → [답변 정리] → [세션 기록] → [세션 왕복 대역] → [맥락 재작성]
//
// [왜 로직을 새로 쓰지 않나]
// ④ 가 ② 를 대변하지 못하면 점수는 ② 에 대한 말이 아니게 된다. 아래 SRC 는 ② 의 Code
// 노드 jsCode 를 **한 글자도 바꾸지 않고** JSON 문자열로 박아 둔 것이다(적용 스크립트가
// 살아 있는 ② 에서 받아 채운다). **손으로 고치지 마라** — bench/parity.py 가 ② 와 바이트
// 대조한다. 고쳐야 할 것이 있으면 ② 를 고치고 이 노드를 다시 만들어라.
//
// [왜 Postgres 표를 쓰지 않나]
// `세션 저장` INSERT → `세션 로드` SELECT 가 하는 일은 열 이름 넷을 바꾸고 경과 초를 재는
// 것뿐이다(rag_chat_sessions 는 일곱 열이 전부 text 라 잘림도 없다). 표를 쓰면 평가 실행이
// ② 의 실사용 세션 표에 행을 쌓는다 — 세션 키를 갈라도 표는 그대로 오염된다.
// 그 왕복만 아래에서 그대로 흉내 내고, 표는 건드리지 않는다.

// ②-SRC ② 의 노드 원문 — 손대지 마라. 적용 스크립트가 ② 에서 받아 채운다.
const SRC = {
 "맥락 재작성": "// ── 맥락 재작성 ──────────────────────────────────────────────────────────────
// 직전 턴(세션 로드)이 살아 있고 이번 질문이 "혼자서는 못 읽히는" 질문일 때만
// 검색용 질문을 다시 쓴다. 그 외에는 아무것도 하지 않는다 — question 이 한 글자도
// 안 바뀌므로 임베딩·검색·게이트·선별·프롬프트가 전부 지금과 바이트 단위로 같다.
//
// [왜 검색용만 바꾸나]
// 재작성은 추측이다. 추측을 답변 프롬프트의 "질문" 자리에 넣으면 잘못 추측했을 때
// 사용자가 하지도 않은 질문에 답하게 된다. 검색은 틀려도 게이트가 막아주지만
// 답변은 막아줄 게 없다. 그래서 프롬프트에는 원문을 넣고, 직전 턴은 따로
// [대화 맥락] 블록으로 붙여 모델이 스스로 지시어를 풀게 한다.

const TTL_S      = 600;   // 세션 수명(초). Discord 실측 근거는 보고서 참조.
const MAX_TOPIC  = 3;     // 직전 주제어를 몇 개까지 끌어올지
const CONTENT_MAX = 1;    // 지시어가 있을 때, 내용어가 이 개수 이하면 후속으로 본다

// ── 토크나이저 — `근거 판정` 노드의 것을 그대로 가져왔다 (같은 파일을 두 번 쓰지 못해 복제) ──
const TAILS = ["이랑","에서","으로","에게","한테","부터","까지","보다","처럼","마다","대로",
  "밖에","조차","라도","이나","하고","에는","과는","와는","이란","라는","이라",
  "은지","는지","한지","인지","이야","예요","이에","해줘","해야","하는",
  "랑","와","과","은","는","이","가","을","를","의","에","도","만","로","다",
  "요","야","지","고","서","며","면","나","까","죠","네","군","데","해","라","게","걸","건"];
const STOP = new Set(("뭐 뭘 뭔 뭐야 뭐가 뭔지 무슨 무엇 어떻 어떻게 어떤 어디 언제 누가 얼마 얼마나 왜 " +
  "알려 알려줘 설명 설명해 정리 가르쳐 말해 얘기 이야기 " +
  "차이 다른 다르 달라 비교 각각 중에 중 골라 골라야 선택 고르 골랐 " +
  "써 쓰 쓸 쓴 쓰나 쓰면 쓰는 써야 썼어 썼 사용 적용 " +
  "필요 이유 방법 관계 정확 자꾸 헷갈 헷갈리 그냥 그리고 좀 진짜 혹시 대해 대한 관련 " +
  "에서 으로 에게 한테 부터 까지 보다 처럼 이랑 하고 " +
  "것 거 게 건 걸 수 때 때문 경우 정도 부분 내용 문제 이거 그거 저거 이런 그런 " +
  "있어 없어 되나 되는 된다 맞아 맞나 인가 일까 할까 하면 한다 이란 라면").split(/\s+/));

// ── 지시어 — 두 갈래를 구분한다 ─────────────────────────────────────────────
// REF(지시대명사/지시관형사)  "그건 왜 비싸?"  → **가리키는 대상이 앞 차례에 있다**
// CONN(담화 접속부사)        "그럼 임베딩은?" → 앞 차례를 잇기만 할 뿐 가리키지 않는다
// 둘을 섞으면 "그럼 임베딩은 뭐야?"(주제 전환)에 직전 주제를 덧붙여 검색을 망친다.
// 실제로 그 질문은 실행 2121 에 있다 — 임베딩만으로 충분히 검색되는 질문이다.
// 그래서 **재작성 스위치는 REF 만** 켠다. CONN 은 내용어가 0일 때만(= 검색할 말이
// 아예 없을 때만) 의미를 갖는다.
//
// 원형(raw run)에 대고 맞춘다. 꼬리를 떼고 집합에 넣는 방식은 "저는"(=나는) → "저",
// "이야기" → "이" 처럼 지시어가 아닌 말을 지시어로 만든다.
// 맨 "그"/"이"/"저" 는 조사 없이 홀로 선 관형사일 때만 인정한다("그 리랭킹" ○, "저는" ✗).
const PART = "(?:[은는이가을를도만의랑와과]|에|에서|로|으로|라도|까지|부터)*";
// **지시대명사만** 방아쇠로 삼는다. 지시관형사(그런/이런/저런)와 맨 관형사(그/이/저)는 뺐다 —
// 그것들은 언제나 뒤따르는 명사를 꾸미고, 그 명사가 곧 내용어라 질문이 혼자 못 서는 경우가
// 드물다. 넣어 봤더니 "그 얘기 말고 데드락 조건 알려줘" 가 후속으로 오판됐다
// (꼬리 제거기가 "조건"→"조" 로 깎아 내용어를 1개로 세는 바람에 문턱을 넘었다).
// 빼도 잃는 게 없다 — "그런 거 언제 써?" 같은 건 내용어가 0이라 규칙 ①이 이미 잡는다.
const REF  = new RegExp("^(?:그것|그거|그건|그걸|그게|이것|이거|이건|이걸|이게|" +
  "저것|저거|저건|저걸|저게|그놈|그분|그때|그쪽|걔|얘|쟤|얘네|걔네|" +
  "거기|저기|여기|아까|방금)" + PART + "$");
const CONN = /^(?:그럼|그러면|그래서|그런데|근데|그리고|그래|그러니까)$/;
// CONT(이어달라는 말) — **방금 한 말을 더 달라는 요청**. 2026-09-16 추가.
// rag_refusals 44·45·46(`더 자세히 알려줘` · `judge 더 자세히 알려줘` ×2)이 근거다.
// 셋 다 스레드 안이었고 세션이 살아 있었는데(age 16.8s·20.2s·13.7s) 후속으로 안 잡혔다.
// 지시대명사가 없어서다. 그런데 이건 대화에서 가장 흔한 후속이다.
//
// [REF/CONN 과 무엇이 다른가]
// REF 는 앞 차례를 **가리키고**, CONN 은 **잇는다**. CONT 는 앞 차례를 **되풀이해 달라고
// 한다** — 그래서 주제어를 하나도 담지 않는다. "그럼 임베딩은 뭐야?"(CONN + 새 주제)와
// 달리 CONT 만으로는 검색할 말이 아예 안 나온다. 그 성질을 그대로 방아쇠로 쓴다:
// **내용어가 전부 CONT 일 때만** 후속으로 본다(아래 규칙 ③). 그래서 새 주제가 하나라도
// 섞이면(`임베딩 더 자세히 알려줘`) 방아쇠가 안 걸린다 — 오염의 문을 규칙으로 닫는다.
//
// 원형(raw run)에 대고 맞춘다. 어간에 대고 맞추면 "더라"→"더" 처럼 엉뚱한 말이 걸린다.
// 굴절형은 손으로 나열한다 — 집합이 작을수록 오염 위험이 작다.
const CONT = /^(?:자세히|자세하게|자세한|상세히|상세하게|상세한|더자세히|더|더더|좀더|조금더|계속|이어서|추가로|예시)$/;
// 재작성 **방아쇠는 아니지만** 재작성할 때는 걷어내는 말. 지시관형사와 맨 관형사가 여기 온다.
// "그런 거 언제 써?" → 규칙 ①(내용어 0)로 후속이 되고, 재작성문에서 "그런"은 빠진다.
const FILL = /^(?:그런|이런|저런|그|이|저)$/;

const RUN = /[가-힣]+|[A-Za-z0-9]+(?:[-+.][A-Za-z0-9]+)*/g;

function stems(q) {
  const out = [];
  for (const run of String(q || "").match(RUN) || []) {
    let t = run, latin = /^[A-Za-z0-9]/.test(run);
    if (latin) t = t.toLowerCase();
    else for (const tl of TAILS) {
      if (t.length > tl.length && t.endsWith(tl)) { t = t.slice(0, -tl.length); break; }
    }
    out.push({ run, t, latin });
  }
  return out;
}

// 내용어 = 지시어도 골격어도 아닌 2자 이상 어간 (중복 제거, 등장 순서 유지).
// 영문은 원형을 그대로 돌려준다 — 검색 질문에 다시 넣을 때 "JWT" 가 "jwt" 로 뭉개지지 않게.
// dropCont 를 켜면 CONT 도 함께 뺀다. **기본값(생략)은 지금까지와 한 글자도 다르지 않다** —
// 단발 질문의 ctxTopic/ctxContentWords 가 바이트 그대로 남아야 해서 기본 경로는 안 건드린다.
// 켜는 곳은 두 군데뿐이고 둘 다 **후속일 때만** 도는 자리다(규칙 ③ 판정 · 재작성 topic).
function contentWords(q, dropCont) {
  const out = [], seen = new Set();
  for (const { run, t, latin } of stems(q)) {
    if (isRef(run) || isConn(run)) continue;
    if (dropCont && isCont(run)) continue;
    if (t.length < 2 || STOP.has(t)) continue;
    if (!seen.has(t)) { seen.add(t); out.push(latin ? run : t); }
  }
  return out;
}
const isRef  = (run) => REF.test(run);
const isConn = (run) => CONN.test(run);
const isCont = (run) => CONT.test(run);
function hasRef(q)  { return (stems(q) || []).some(({ run }) => isRef(run)); }
function hasConn(q) { return (stems(q) || []).some(({ run }) => isConn(run)); }
function hasCont(q) { return (stems(q) || []).some(({ run }) => isCont(run)); }

// 지시어 낱말을 통째로 걷어낸 나머지 — 재작성의 뼈대가 된다
function stripDeictic(q) {
  let s = String(q || "");
  for (const { run } of stems(q)) {
    // CONT 는 **2자 이상일 때만** 걷어낸다. 이 치환은 정규식이 아니라 부분 문자열
    // 치환(split/join)이라, 한 글자 "더" 를 지우면 같은 문장의 "더미데이터" 까지
    // "미데이터" 로 깎인다. 한 글자를 남겨도 잃는 게 없다 — "더" 는 어차피 내용어가
    // 아니라(어간 1자) 검색어에 실리지 않는다.
    const cont2 = isCont(run) && run.length >= 2;
    if (isRef(run) || isConn(run) || cont2 || FILL.test(run)) s = s.split(run).join(" ");
  }
  return s.replace(/\s+/g, " ").replace(/^[\s,.]+/, "").trim();
}

// ── 본체 ────────────────────────────────────────────────────────────────────
const q0 = $('질문 정리').first().json;
const question = String(q0.question || "");

let sess = {};
try { sess = $input.first().json || {}; } catch (e) { sess = {}; }

const prevQ     = String(sess.prev_question || "");
const prevLead  = String(sess.prev_answer || "");
const prevTopic = String(sess.prev_topic || "");
const ageS      = (sess.age_s === null || sess.age_s === undefined) ? null : Number(sess.age_s);
const alive     = !!prevQ && ageS !== null && isFinite(ageS) && ageS >= 0 && ageS < TTL_S;

const words  = contentWords(question);
const ref    = hasRef(question);
const conn   = hasConn(question);
const cont   = hasCont(question);
// 내용어에서 CONT 를 뺀 나머지 = **이번 질문이 스스로 들고 온 주제**.
// 0이면 이 질문은 혼자 설 수 없다. 1개라도 있으면 새 주제를 꺼낸 것이므로 건드리지 않는다.
const ownTopic = cont ? contentWords(question, true).length : words.length;
// 후속 판정 — 셋 중 하나
//   ① 내용어가 아예 없다 → 이 질문만으로는 검색어를 만들 수 없다(접속부사만 있어도 해당)
//   ② 지시대명사가 있고 내용어가 CONTENT_MAX 이하 → 지시어가 빠진 자리를 앞 차례가 채운다
//   ③ 이어달라는 말이 있고 **내용어가 전부 그것뿐**이다 → 되풀이 요청. 주제는 앞 차례에 있다
//      ③ 은 문턱이 개수가 아니라 **0** 이다. "몇 개까지 봐준다" 로 두면 `임베딩 더 자세히
//      알려줘`(새 주제 1개 + CONT)가 걸려 앞 주제에 붙는다 — 가장 위험한 경계라 아예 닫았다.
//      대신 그런 질문은 게이트가 막았을 때만 아래 재검색이 한 번 더 시도한다.
const needy  = words.length === 0 || (ref && words.length <= CONTENT_MAX)
               || (cont && ownTopic === 0);
const isFollowUp = alive && needy;

// 재작성문 만들기. 1차 판정과 재검색(아래)이 **같은 함수**를 쓴다 — 두 벌로 갈라지면
// "게이트가 막은 질문을 무엇으로 다시 물었나" 가 1차 규칙과 달라진다.
function rewrite() {
  // 직전 주제어: 직전 질문에서 뽑되, 직전 질문도 후속이었다면 이월된 topic 을 쓴다.
  // CONT 를 빼고 뽑는다 — 직전 질문이 `더 자세히 알려줘` 였으면 주제어가 "자세히" 로
  // 잡혀 그 오염이 다음 턴으로 번진다(실행 2995 가 실제로 그랬다: prev_topic="자세히").
  // 빼고 나면 비게 되고, 그때는 아래 fallback 이 이월된 prevTopic 을 집어 준다 — 옳다.
  let topic = contentWords(prevQ, true).slice(0, MAX_TOPIC).join(" ");
  if (!topic) topic = prevTopic;
  // 질문이 **이미 들고 있는** 주제어는 빼고 붙인다. 안 그러면 `judge 더 자세히 알려줘` 의
  // 재검색이 `judge judge 더 알려줘` 가 되어 같은 낱말이 두 번 들어가고 임베딩이 그쪽으로
  // 쏠린다(2026-09-18 실측: 표본 5개 전부에서 best2mean 이 0.03~0.08 나빠졌다).
  // 재검색은 게이트가 이미 막은 뒤에만 도는 경로라 그 폭이 당락을 가른다.
  // **빼기만 한다** — 없던 낱말을 넣지 않으므로 겹치지 않는 질문은 한 글자도 안 바뀐다.
  const own = new Set(contentWords(question).map(function (w) { return String(w).toLowerCase(); }));
  topic = topic.split(" ").filter(function (w) { return w && !own.has(w.toLowerCase()); }).join(" ");
  const rest = stripDeictic(question);
  const q = (topic + " " + rest).replace(/\s+/g, " ")
              .replace(/\s+([?!.,])/g, "$1").trim() || question;
  const block = "[대화 맥락 — 바로 앞 차례]\n" +
                "이전 질문: " + prevQ + "\n" +
                (prevLead ? "이전 답변 요지: " + prevLead + "\n" : "") +
                "위 맥락을 참고해 아래 질문의 지시어(그것/그건/그럼 …)가 무엇을 가리키는지 판단하세요.\n\n";
  return { q: q, block: block };
}

let searchQuestion = question;
let contextBlock   = "";
if (isFollowUp) {
  const r = rewrite();
  searchQuestion = r.q;
  contextBlock   = r.block;
}

// ── 재검색용 예비 재작성 — 여기서는 **쓰지 않는다** ─────────────────────────
// 아래 두 값은 이번 차례의 검색에 한 글자도 영향을 주지 않는다. ② 가 맨몸 질문으로
// 먼저 검색하고, **게이트가 막았을 때만** 이 값으로 한 번 더 검색한다.
//
// [왜 CONN 을 여기서는 방아쇠로 쓰나]
// 1차에서 CONN(그럼/그러면/그래서/근데)을 방아쇠로 쓰면 주제 전환 질문이 오염된다 —
// "그럼 임베딩은 뭐야?"(실행 2121)가 "리랭킹 임베딩은 뭐야?" 로 재작성된다.
// 그런데 그 질문은 게이트를 **넉넉히** 통과한다(실측 best2mean 0.3572 < NEAR 0.420).
// 통과하면 재검색은 아예 돌지 않으므로 오염될 자리가 없다. 반대로 "그러면 많이 비쌈?"
// (실행 2636)은 막힌다(best2mean 0.4937, lexHit 0.50). 막힌 질문에만 맥락을 붙이는 것이
// 이 설계다 — **판정을 규칙이 아니라 이미 있는 게이트에 맡긴다.**
//
// [문턱을 1차보다 한 칸 넉넉히 두는 이유]
// 1차(CONTENT_MAX=1)보다 느슨한 2로 둔다. 게이트가 이미 한 번 걸러 준 뒤라 오판의
// 대가가 작고, "그러면 리랭크 많이 비쌈?" 처럼 내용어 2개짜리 후속이 실제로 있다.
// 그래도 REF/CONN 이 **없는** 질문은 절대 대상이 아니다 — "러스트의 소유권 알려줘" 가
// 막혔다고 앞 차례 주제를 붙여 되살리면 사용자가 하지도 않은 질문에 답하게 된다.
const RETRY_CONTENT_MAX = 2;
// 1차에서 이미 재작성했다면(isFollowUp) 재검색해 봐야 같은 질문이라 뜻이 없다.
// CONT 도 여기서는 방아쇠다. 1차 규칙 ③ 은 "내용어가 전부 CONT" 일 때만 걸리므로
// `judge 더 자세히 알려줘`(내용어 judge 1개 + CONT)는 1차에서 일부러 흘려보낸다.
// 그 질문은 게이트가 막는다(실측: best2mean 0.4978 · lexHit 0.50 · 실행 2995/2997).
// 막힌 뒤에만 맥락을 붙여 되묻는다 — 통과했으면 재검색은 아예 돌지 않아 오염될 자리가 없다.
// `임베딩 더 자세히 알려줘` 도 같은 규칙을 탄다: 통과하면 그대로, 막히면 되묻는다.
//
// CONT 방아쇠에만 `ownTopic <= 1` 을 더 건다. CONT 낱말은 이어달라는 요청 말고
// **비교 부사**로도 쓰인다 — `더 빠른 인덱스 뭐 있어?` 의 "더" 가 그렇다. 그건 스스로
// 주제를 둘(빠른·인덱스) 들고 온 새 질문이라 되물을 일이 아닌데, 개수 문턱만으로는
// 2개까지 통과해 버린다. "내가 들고 온 주제가 1개 이하일 때만" 으로 좁히면
// `judge 더 자세히 알려줘`(judge 1개)는 남고 `더 빠른 인덱스`(2개)는 빠진다.
// REF/CONN 방아쇠는 지금까지와 한 글자도 다르지 않다.
const retryNeedy = alive && !isFollowUp
                   && ((ref || conn) || (cont && ownTopic <= 1))
                   && words.length <= RETRY_CONTENT_MAX;
let ctxRetryQuestion = "";
let ctxRetryContext  = "";
if (retryNeedy) {
  const r = rewrite();
  if (r.q !== searchQuestion) { ctxRetryQuestion = r.q; ctxRetryContext = r.block; }
}

// 이월 topic — 이번 턴이 무엇에 관한 것이었는지. 후속이면 직전 것을 물려받는다.
const carry = contentWords(searchQuestion).slice(0, MAX_TOPIC).join(" ") || prevTopic;

return [{
  json: {
    ...q0,
    question: searchQuestion,   // ← 하류(검색·게이트·선별)가 읽는 질문
    rawQuestion: question,      // ← 사용자가 실제로 친 말. 답변 프롬프트가 읽는다
    contextBlock,               // ← 후속일 때만 비어 있지 않다
    ctxFollowUp: isFollowUp,
    ctxTopic: carry,
    ctxAgeS: ageS,
    ctxPrevQuestion: prevQ,
    ctxRef: ref,
    ctxConn: conn,
    ctxContentWords: words.length,
    // ↓ 재검색 전용. 이번 검색에는 안 쓰인다 — ② `재검색 판정` 이 게이트 결과를 보고 쓴다.
    ctxCanRetry: !!ctxRetryQuestion,
    ctxRetryQuestion,
    ctxRetryContext,
  },
}];
",
 "세션 기록": "// ── 세션 기록 ────────────────────────────────────────────────────────────────
// 이번 차례를 세션 표에 남길 모양으로 만든다. Reply 뒤에 붙어 있으므로 여기서 무엇을 하든
// 사용자가 체감하는 응답 시간에는 영향이 없다.
//
// [왜 실패한 차례도 남기나]
// 남기지 않으면 "근거 없음"으로 끝난 다음의 "그건 …" 이 **두 차례 전** 주제를 가리키게 된다.
// 사용자 입장에서는 방금 못 찾겠다고 한 것을 되묻는 건데 엉뚱한 옛 주제가 붙는 셈이다.
// 실패도 기록해 두면 그 되묻기는 같은 주제로 다시 실패한다 — 정직하고 예측 가능하다.
const c = $('맥락 재작성').first().json;
const q = $('질문 정리').first().json;

let lead = '';
try {
  const t = String($('답변 정리').first().json.text || '').trim();
  lead = (t.split('\n').find((l) => l.trim()) || '').replace(/\*\*/g, '').trim().slice(0, 200);
} catch (e) { lead = ''; }        // 근거 없음 분기 — text 가 '' 라 리드도 빈다

// 코어가 서브워크플로로 나가면서 $('노트 선별') 을 더 이상 볼 수 없다. 대신 코어의 출력을 읽는다.
// 차단된 차례에 '없음' 이 아니라 빈 문자열을 넣는 것은 예전 동작 그대로다 —
// 예전에는 `노트 선별` 이 아예 안 돌아 catch 로 빠졌다.
let sources = '';
try {
  const r = $('RAG 코어').first().json;
  sources = r.grounded ? String(r.sourcesLine || '') : '';
} catch (e) { sources = ''; }

return [{
  json: {
    session_key: [q.guildId, q.channelId, q.authorId].join(':'),
    question: c.rawQuestion || c.question || '',
    answer_lead: lead,
    topic: c.ctxTopic || '',
    sources: sources,
  },
}];
",
 "답변 정리": "// 답변을 Discord에서 읽히는 모양으로 정규화한다. 내용은 건드리지 않고 배치와 라벨만 손본다.
//
// [왜 필요한가]
// 형식 규칙(첫 줄 핵심 문장, `- **용어**: 설명` 불릿)은 프롬프트로 "부탁"한 것이라
// gemma3:4b가 temperature 0.4에서 종종 통째로 무시한다. 실측 4건 중 2건이 그랬다.
//   실행 2106 — 658자를 개행 0개로 뱉어 한 문단이 됐다
//   실행 2122 — 리드 문장 없이 라벨 없는 맨 문장 불릿 17개
//   실행 2124 — 같은 모양으로 11개
// 잘 나온 답변(2120/2121)과 비교하면 차이는 딱 둘이다: 리드 문장이 있느냐, 불릿에
// 굵은 라벨이 있느냐. 라벨이 없으면 눈이 걸릴 데가 없어 전부 읽어야 한다.
//
// [하는 일] 내용은 한 글자도 바꾸지 않는다. 없는 문장을 지어내지도, 불릿을 합치지도 않는다.
//   1) 줄 중간에 뭉친 불릿을 제 줄로 내린다
//   2) 리드 문장이 없으면 첫 불릿을 리드로 올린다 (문장이 이미 거기 있다)
//   3) 라벨 없는 불릿의 머리 주제어를 굵게 만든다 (보수적으로 — 애매하면 그냥 둔다)
//   4) 블록으로 재조립해 빈 줄을 정리한다
// 2~3은 이미 형식을 지킨 답변에는 아무 일도 하지 않는다.

const HEAD = '(?:💡\\s*)?\\*\\*[^*\\n]{1,40}\\*\\*\\s*[:：]';

let t = String($json.text || '').trim();

// 0) 출처 표기를 걷어낸다. 형식 규칙에 "출처나 파일명은 쓰지 말 것"이라고 적혀 있지만
//    프롬프트가 근거를 [출처: 경로] 헤더와 함께 싣기 때문에 모델이 종종 그대로 베낀다
//    (실측: 벤치 답변 55건 중 11건에 위키링크가 샜고, 문장 끝 (출처: …) 형태도 관측됐다).
//    출처는 Reply to Discord 가 실제로 쓴 노트만 골라 따로 붙이므로 본문에 있으면 중복이자 노이즈다.
//    근거 규칙과 같은 이유로, 프롬프트에 부탁하는 대신 여기서 지운다.
t = t
  .replace(/[（(]\s*출처\s*[:：][^)）]*[)）]/g, '')   // 문장 끝 (출처: study/x.md)
  .replace(/\[\s*출처\s*[:：][^\]]*\]/g, '')        // 프롬프트 헤더를 그대로 베낀 [출처: …]
  .replace(/\[\[([^\]|]*\|)?([^\]]*)\]\]/g, '$2') // 옵시디언 위키링크 — 표시 텍스트만 남긴다
  .replace(/(?:^|\n)\s*출처\s*[:：][^\n]*/g, '')     // "출처: …" 로 시작하는 줄 통째
  .replace(/(\S)[ \t]{2,}/g, '$1 ')                  // 지운 자리에 생긴 연속 공백
                                                    // (줄 앞 들여쓰기는 건드리지 않는다 — 중첩 불릿이 있다)
  .replace(/\s+([.,!?)\]])/g, '$1')                  // 구두점 앞에 남은 공백
  .replace(/[ \t]+$/gm, '');

// 1) 앞에 개행 없이 붙어 있는 불릿을 제 줄로 내린다 (개행 뭉침 사고 복구)
// 앞이 공백이 아닐 때만 자른다. [^\\n] 은 공백도 먹어서 들여쓴 중첩 불릿의
// 들여쓰기까지 삼켰다 (2026-09-14 발견 — 주석은 보존한다고 적혀 있는데 코드가 반대였다).
t = t.replace(new RegExp('(\\S)[ \\t]+[-•*][ \\t]+(?=' + HEAD + ')', 'g'), '$1\n- ');
// 불릿 기호 통일 — Discord는 •를 목록으로 렌더하지 않는다
t = t.replace(/^[ \t]*[•*][ \t]+/gm, '- ');

// 빈 줄을 버리지 않는다. 2026-09-15 이전에는 전부 버리고 블록 사이에만 다시 넣었는데,
// 그러면 비교형(리드 문장 + **A** / **B** 대조 줄)이나 산문 단락의 의도한 빈 줄이 먹혀
// 문단이 통째로 붙어 나온다. 이제는 모델이 넣은 빈 줄을 존중하고 과한 것만 줄인다.
let lines = t.split('\n').map((l) => l.replace(/[ \t]+$/, ''));
while (lines.length && lines[0] === '') lines.shift();
while (lines.length && lines[lines.length - 1] === '') lines.pop();
// 들여쓴 중첩 불릿도 목록으로 본다. 안 그러면 블록 재조립이 중첩 항목을 목록에서
// 떼어내 앞뒤에 빈 줄을 넣어버린다.
const isBullet = (l) => /^\s*-\s/.test(l);

// 2) 첫 줄이 불릿이면 리드 문장이 없다는 뜻 — 첫 불릿을 끌어올린다.
//    불릿이 3개 미만이면 건드리지 않는다(짧은 답변에서 목록이 사라지면 더 이상하다).
const firstIdx = lines.findIndex((l) => l !== '');
if (firstIdx !== -1 && isBullet(lines[firstIdx]) && lines.filter(isBullet).length >= 3) {
  const lead = lines[firstIdx]
    .replace(/^-\s+/, '')
    .replace(/^(?:💡\s*)?\*\*([^*\n]+)\*\*\s*[:：]\s*/, '$1: ') // 리드는 굵게 쓰지 않는 게 규칙이다
    .replace(/\*\*/g, '');
  lines = [lead].concat(lines.slice(firstIdx + 1));
}

// 3) 라벨 없는 불릿의 머리 주제어를 굵게.
//    "임베딩 모델은 텍스트를 …" → "**임베딩 모델**: 텍스트를 …"
//    보수적으로 간다 — 조사 은/는 앞이 2~14자이고, 문장부호가 없고, 어미(…다)로 끝나지
//    않을 때만. "점수비가 크다는 건 …" 같은 관형절을 주제어로 오인하지 않기 위해서다.
//    조사 이/가는 제외한다("리랭커가 …"는 주제어가 아닌 경우가 많다).
// 수량자를 게으르게 둔다. 탐욕적이면 문장 뒤쪽 조사를 잡아
//   "M2는 실험으로 같은 결론에…" → 머리를 "M2는 실험으로 같"으로 오려낸다.
const LABEL = /^-\s+([^\s*:：.,!?()[\]]{1,6}?(?:\s[^\s*:：.,!?()[\]]{1,10}?){0,2}?)(은|는)\s+(.+)$/;
lines = lines.map((l) => {
  if (!isBullet(l) || l.includes('**')) return l;      // 이미 라벨이 있으면 그대로
  const m = l.match(LABEL);
  if (!m) return l;
  const head = m[1];
  if (head.length < 2 || head.length > 14) return l;
  if (/다$/.test(head)) return l;                      // 관형절("…크다는 건")을 주제어로 오인하지 않는다
  return '- **' + head + '**: ' + m[3];
});

// 4) 빈 줄 정규화 — 모델이 넣은 것은 살리고, 과한 것만 줄이고, 목록 앞은 한 줄 띄운다.
//    (블록을 통째로 재조립하던 방식은 대조·산문 형식의 문단을 뭉개서 버렸다.)
const out = [];
for (let k = 0; k < lines.length; k++) {
  const line = lines[k];
  if (line === '') {
    if (out.length && out[out.length - 1] !== '') out.push('');  // 연속 빈 줄은 하나로
    continue;
  }
  // 목록이 시작되는데 앞이 본문이면 한 줄 띄운다
  const prev = out.length ? out[out.length - 1] : null;
  if (prev && prev !== '' && isBullet(line) && !isBullet(prev)) out.push('');
  out.push(line);
}
t = out.join('\n');

return [{ json: { ...$json, text: t } }];
"
};
// ②-SRC 여기까지
const run = (name, j, dollar, inp) =>
  new Function('$json', '$', '$input', SRC[name])(j, dollar, inp);
const NO = (n) => { throw new Error('no node ' + n); };
const one = (j) => ({ first: () => ({ json: j }) });

const row   = $('1차 준비').first().json;
const core1 = $('RAG 코어(선행)').first().json;

// ── 선행 턴을 ② 의 "첫 차례" 로 재생 ───────────────────────────────────────
// ② 의 첫 차례는 세션이 비어 있다(처음 말을 걸었거나 TTL 이 지났다). 그때 `맥락 재작성` 은
// 아무것도 하지 않고 ctxTopic 만 계산한다 — `세션 기록` 이 그 값을 topic 으로 쓴다.
const q0a = { question: row.mtPrev };
const c1 = run('맥락 재작성', {}, (n) => (n === '질문 정리' ? one(q0a) : NO(n)), one({}))[0].json;
// ② 는 코어 출력을 **그대로** `답변 정리` 에 넣는다. 차단된 차례는 text 가 '' 라 리드도 빈다.
const t1 = run('답변 정리', core1, NO, one(core1))[0].json;
const rec = run('세션 기록', {}, (n) => {
  if (n === '맥락 재작성') return one(c1);
  if (n === '질문 정리')   return one(q0a);
  if (n === '답변 정리')   return one(t1);
  if (n === 'RAG 코어')    return one(core1);   // ④ 에서는 선행 턴을 부른 노드가 그 자리다
  return NO(n);
}, one({}))[0].json;

// ── 세션 왕복 대역 ─────────────────────────────────────────────────────────
// age_s 는 Postgres numeric 이라 **문자열**로 돌아온다. `맥락 재작성` 의 Number() 가 그걸
// 전제하고 있으므로(bench/parity.py 주석 참조) 여기서도 문자열로 넘긴다.
const ageS = Math.max(0, (Date.now() - Number(row.mtT0 || Date.now()))) / 1000;
const sess = {
  prev_question: rec.question,     // 세션 저장 question    → 세션 로드 prev_question
  prev_answer:   rec.answer_lead,  //              answer_lead →           prev_answer
  prev_topic:    rec.topic,        //              topic       →           prev_topic
  age_s:         String(ageS),     //              updated_at  →           age_s (EXTRACT EPOCH)
};

// ── 후속 턴을 ② 의 "다음 차례" 로 재생 ─────────────────────────────────────
const q0b = { question: row.mtFollow };
const c2 = run('맥락 재작성', {}, (n) => (n === '질문 정리' ? one(q0b) : NO(n)), one(sess))[0].json;

// `답변 저장` 이 읽어 갈 자리. 노드 참조로 넘기면 루프에서 앞 문항 값이 잡힌다.
$getWorkflowStaticData('global').mtLast = {
  prevGrounded: !!core1.grounded,
  prevLead: rec.answer_lead,
  ageS,
};

return [{
  json: {
    ...row,
    ...c2,                              // question(재작성) · rawQuestion(원문) · contextBlock · ctx*
    mtPrevGrounded: !!core1.grounded,   // 선행 턴이 차단됐으면 후속 점수가 그 탓일 수 있다
    mtPrevLead: rec.answer_lead,
    mtAgeS: ageS,
    // bench/parity.py 가 이 실행 기록을 `맥락 재작성` 대조 표본으로 쓴다.
    // (q0, sess) 쌍이 있어야 배포 JS 를 다시 돌려 볼 수 있다 — mtFollow 가 q0 다.
    mtSess: sess,
  },
}];

// 주기 작업의 "지금이 차례인가" 게이트.
//
// 이 맥북은 00~06시 KST 에 자서 **고정 시각 스케줄이 한 번도 뜬 적이 없다**
// (2026-09-18 실측: 14일 보존 기간 안에 ④·⑤ 의 trigger 모드 실행 0건.
//  가동률이 가장 높은 22시도 64% 라 어느 고정 시각도 안전하지 않다).
//
// 그래서 6시간마다 뜨고, 앞의 `주간 차례 확인` 이 차례를 **원자적으로** 집는다:
// 7일이 안 지났으면 그 INSERT ... ON CONFLICT ... WHERE 가 0행을 돌려주고,
// 여기서 걸러져 아래로 아무것도 안 내려간다. 조회하고 나서 쓰는(check-then-act)
// 방식이 아니라 한 쿼리라 동시 실행이 겹쳐도 두 번 돌지 않는다.
//
// 수동 실행(웹훅) 경로는 이 게이트를 **지나지 않는다** — 언제든 바로 돈다.
return $input.all().filter((i) => i && i.json && i.json.job);
